import styled from '@emotion/styled';

const TOTAL_PHI_BIG_NUMBER_CLASS = 'portfolio-health-total-phi-big-number';

export const StyledTotalPhiCard = styled.div({
  width: 'fit-content',
  maxWidth: '100%',

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS}.bigNumberCard`]: {
    width: 'fit-content',
    maxWidth: '100%',
    borderRadius: '12px',
  },

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS}.bigNumberContainer`]: {
    width: 'fit-content',
    maxWidth: '100%',
    padding: '24px',
    gap: '16px',
  },

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS} .bigNumberBody`]: {
    width: 'fit-content',
    padding: 0,
    justifyContent: 'flex-start',
    alignItems: 'flex-start',
  },

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS} .bigNumberItemContainer`]: {
    display: 'flex',
    flexDirection: 'row',
    flexWrap: 'nowrap',
    gap: '24px',
    justifyContent: 'flex-start',
    width: 'auto',
    gridTemplateColumns: 'unset',
  },

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS} .bigNumberItemContainer > div`]: {
    flex: '0 0 auto',
    alignItems: 'flex-start',
    textAlign: 'left',
    minWidth: 0,
  },

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS} .bigNumberItemContainer > div > div:first-of-type`]:
    {
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      gap: '8px',
      justifyContent: 'flex-start',
    },

  [`& .${TOTAL_PHI_BIG_NUMBER_CLASS} [data-testid$="-header-title"]`]: {
    fontSize: '20px',
    lineHeight: '120%',
  },
});
